begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('89100000-0000-4000-8000-000000000001','games-played-admin@example.invalid');
insert into public.profiles(id,full_name,role) values ('89100000-0000-4000-8000-000000000001','Games test','admin') on conflict(id) do update set role='admin';
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values ('89100000-0000-4000-8000-000000000002','89100000-0000-4000-8000-000000000001','totp','verified','LOCAL-TEST-ONLY',now(),now());
insert into public.staff_games(slug,name,active) values ('party-games','Party Games',true),('arcade-2-0','Arcade 2.0',true) on conflict(slug) do update set active=true;
insert into public.sessions(id,owner_id,name,date,start_time,max_players,game_options,confirmed_game_id,booking_type,ticket_total_price)
values ('89100000-0000-4000-8000-000000000003','89100000-0000-4000-8000-000000000001','Games fixture',current_date+191,'17:00',1,array['city-z'],'city-z','ticket',240000);
select ok(not has_function_privilege('anon','public.staff_confirm_games_played(uuid,text[],timestamptz)','execute'),'Anon cannot confirm games');
select ok(not has_table_privilege('authenticated','public.staff_session_games_played','insert'),'Direct writes are blocked');
select ok(not has_table_privilege('anon','public.staff_session_games_played','select'),'Anon cannot read confirmations');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"89100000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select throws_ok($q$select public.staff_confirm_games_played('89100000-0000-4000-8000-000000000003',array['city-z'])$q$,'P0001','Staff access required.','MFA is required');
select is((select count(*)::int from staff_session_games_played),0,'Unverified role sees no records');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"89100000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select is((select count(*)::int from staff_game_play_options),55,'Every collection mini-game, mode and map is selectable');
select is((select count(*)::int from staff_playable_games where id in ('laser-limbo','spatial-ops')),2,'Both pop-up games are selectable');
select lives_ok($q$select public.staff_confirm_games_played('89100000-0000-4000-8000-000000000003',array['city-z','party-games:games:car-wash','arcade-2-0:modes:deathmatch','city-z'])$q$,'Multiple games, mini-games and modes save together');
select is((select cardinality(game_ids) from staff_session_games_played where session_id='89100000-0000-4000-8000-000000000003'),3,'Saved selection is deduplicated and readable');
select is((select confirmed_by::text from staff_session_games_played where session_id='89100000-0000-4000-8000-000000000003'),'89100000-0000-4000-8000-000000000001','Confirmation records staff actor');
select is((select confirmed_game_id from sessions where id='89100000-0000-4000-8000-000000000003'),'city-z','Planned game is preserved');
select is((select ticket_total_price from sessions where id='89100000-0000-4000-8000-000000000003'),240000,'Booking price is preserved');
select throws_ok($q$select public.staff_confirm_games_played('89100000-0000-4000-8000-000000000003',array['revolta'])$q$,'P0001','Games played changed. Reload before saving.','Stale edit cannot overwrite confirmation');
select throws_ok($q$select public.staff_confirm_games_played('89100000-0000-4000-8000-000000000003',array['invented-game'],(select updated_at from staff_session_games_played where session_id='89100000-0000-4000-8000-000000000003'))$q$,'P0001','Choose available games, mini-games or modes.','Unknown game IDs are rejected');
select lives_ok($q$select public.staff_confirm_games_played('89100000-0000-4000-8000-000000000003','{}',(select updated_at from staff_session_games_played where session_id='89100000-0000-4000-8000-000000000003'))$q$,'Staff can explicitly clear a selection');
select is((select cardinality(game_ids) from staff_session_games_played where session_id='89100000-0000-4000-8000-000000000003'),0,'Empty selection persists');
select * from finish();
rollback;
